import pyomo.environ as pyo

DATA = {
    "num_days": 7,
    "shift_length": 5,       # consecutive working days
    "days_off": 2,           # consecutive days off
    # required employees, in day order: Mon, Tue, Wed, Thu, Fri, Sat, Sun
    "requirements": {0: 15, 1: 13, 2: 15, 3: 18, 4: 14, 5: 16, 6: 10},
    # coverage matrix: a[d][i] == 1 if day d is worked by a group starting on day i
    "coverage": {
        d: {i: (1 if (d - i) % 7 < 5 else 0) for i in range(7)}
        for d in range(7)
    },
}


def build_model(data=None):
    d = data or DATA

    model = pyo.ConcreteModel()

    # ---- Set: days of the week (index by integer 0..6) ----
    model.days = pyo.RangeSet(0, d["num_days"] - 1)

    # ---- Variable: number of employees whose shift starts on day i ----
    def x_bounds(m, i):
        return (0, None)
    model.x = pyo.Var(model.days, within=pyo.NonNegativeIntegers, bounds=x_bounds)

    # ---- Objective: minimise total number of workers ----
    def obj_rule(m):
        return pyo.summation(m.x)
    model.obj = pyo.Objective(rule=obj_rule, sense=pyo.minimize)

    # ---- Constraint: weekly requirement satisfied every day ----
    def meet_requirement_rule(m, day):
        return sum(d["coverage"][day][i] * m.x[i] for i in m.days) >= d["requirements"][day]
    model.meet_requirement = pyo.Constraint(model.days, rule=meet_requirement_rule)

    return model


