import pyomo.environ as pyo

DATA = {
    "DAYS": ["Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"],
    "requirement": {
        "Mon": 15,
        "Tue": 13,
        "Wed": 15,
        "Thu": 18,
        "Fri": 14,
        "Sat": 16,
        "Sun": 10,
    },
    "work_days": 5,
    "rest_days": 2,
}


def build_model(data=None):
    d = data or DATA
    days = d["DAYS"]
    n = len(days)
    work_days = d["work_days"]

    # coverage[t][s] = 1 if an employee starting on day s works on day t
    coverage = {}
    for ti, t in enumerate(days):
        coverage[t] = {}
        for si, s in enumerate(days):
            offset = (ti - si) % n
            coverage[t][s] = 1 if offset < work_days else 0

    model = pyo.ConcreteModel()

    model.DAYS = pyo.Set(initialize=days, ordered=True)

    model.start = pyo.Var(
        model.DAYS,
        within=pyo.NonNegativeIntegers,
    )

    def obj_rule(m):
        return sum(m.start[s] for s in m.DAYS)

    model.obj = pyo.Objective(expr=obj_rule, sense=pyo.minimize)

    def requirement_rule(m, t):
        return sum(coverage[t][s] * m.start[s] for s in m.DAYS) >= d["requirement"][t]

    model.requirement_con = pyo.Constraint(model.DAYS, rule=requirement_rule)

    return model


